-- The MODU-DRILL code key (Code keys -> Drilling -> MODU-DRILL), from the ISCAR
-- e-catalog's MODU-DRILL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.modudrill', $ck${"title": "MODU-DRILL code key – modular bodies, heads and inserts", "subtitle": "Modular drill bodies (28 – 45 mm) carrying three head types: MD-DFN (CHAM-IQ inserts), MD-DR-DH (square inserts, guide pads) and MD-MNC (pilot SUMO-CHAM head and WCGX inserts)", "example": "MD-BODY-33-36-108-32A-3D", "decoder": "modu-drill", "sections": [{"key": "t-family", "title": "Body – family", "sample": "MD-BODY", "rows": [{"code": "MD-BODY", "meaning": "Modular drill body, can carry any of the three head types"}, {"code": "MD-EXTENSION", "meaning": "Modular extension holder (+200 mm overall length)"}]}, {"key": "t-range", "title": "Body – head range", "rows": [{"code": "##-##", "meaning": "Diameter range of the heads it carries in mm (e.g. 33-36)"}]}, {"key": "t-length", "title": "Body – length", "rows": [{"code": "###", "meaning": "Length in mm (inferred)"}]}, {"key": "t-height", "title": "Body – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (32, 40)"}]}, {"key": "t-shank", "title": "Body – shank type", "rows": [{"code": "A", "meaning": "One flat shank"}]}, {"key": "t-depth", "title": "Body – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth ratio (3D, 5D, 8D)"}]}, {"key": "h-family", "title": "Head – family", "sample": "MD-MNC", "rows": [{"code": "MD-DFN", "meaning": "Head carrying CHAM-IQ-DRILL solid carbide inserts"}, {"code": "MD-DR-DH", "meaning": "Head with guide pads carrying square inserts"}, {"code": "MD-MNC", "meaning": "Head with a pilot SUMO-CHAM head and peripheral trigon (WCGX) inserts; with IMH## an IMH pilot head"}]}, {"key": "h-dia", "title": "Head – drilling diameter", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 330 = 33.0 mm)"}]}, {"key": "h-insert", "title": "Head – inserts", "rows": [{"code": "######", "meaning": "MD-DR-DH: square insert size code"}, {"code": "W#", "meaning": "MD-MNC: WCGX insert size (W5 = WCGX 05...)"}]}, {"key": "h-variant", "title": "Head – variant", "rows": [{"code": "##", "meaning": "MD-DR-DH variant (see the catalog) (inferred)"}]}, {"key": "h-imh", "title": "Head – IMH connection", "rows": [{"code": "IMH##", "meaning": "IMH pilot head connection size"}]}, {"key": "h-pilot", "title": "Head – pilot head", "rows": [{"code": "###", "meaning": "Pilot ICP ...-MNC head it carries x10"}]}, {"key": "i-family", "title": "Pilot head / insert – family", "rows": [{"code": "ICP", "meaning": "SUMO-CHAM pilot heads for modular combi drills"}, {"code": "WCGX", "meaning": "Precision ground trigon peripheral inserts for MNC heads"}]}, {"key": "i-dia", "title": "Pilot head – diameter", "rows": [{"code": "###", "meaning": "Drilling diameter x10"}]}, {"key": "i-suffix", "title": "Pilot head / insert – suffix", "rows": [{"code": "MNC #F", "meaning": "For MD-MNC heads (4F) (inferred)"}, {"code": "W", "meaning": "Wiper"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "##", "meaning": "Insert size"}]}, {"key": "i-thick", "title": "Insert – thickness", "rows": [{"code": "##", "meaning": "Insert thickness code"}, {"code": "#T#", "meaning": "Insert thickness code with T"}]}, {"key": "i-radius", "title": "Insert – corner radius", "rows": [{"code": "##", "meaning": "Corner radius x10"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "DC", "meaning": "DC chipformer (see the catalog)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
